<template>
  <div id="app" class="app">
    <h1 @dblclick="getVideoCount">美少女肌地-追溯码视频查询</h1>
    <SearchBox @search="handleSearch" />
    <div v-if="videoUrl" class="result">
      <h2>查询结果</h2>
      <video controls :src="videoUrl" width="400"></video>
    </div>
    <div v-else-if="searched" class="no-result">
      <p>未找到对应视频！</p>
    </div>
  </div>
</template>

<script>
import { ref } from "vue";
import SearchBox from "./components/SearchBox.vue";

export default {
  components: {
    SearchBox,
  },
  setup() {
    const videoUrl = ref(""); // 视频文件路径
    const searched = ref(false); // 是否完成搜索

    const handleSearch = (code) => {
      const filePath = `${process.env.BASE_URL}videos/${code}.MOV`; // 自动适配部署路径
      console.log(`Attempting to fetch video: ${filePath}`); // 调试日志
      fetch(filePath, { method: "HEAD" }) // 检查文件是否存在
        .then((response) => {
          if (response.ok) {
            videoUrl.value = filePath;
          } else {
            videoUrl.value = "";
          }
          searched.value = true;
        })
        .catch(() => {
          videoUrl.value = "";
          searched.value = true;
        });
    };

    const getVideoCount = async () => {
      try {
        const response = await fetch("/videos/");
        if (!response.ok) {
          throw new Error("无法获取视频目录内容");
        }
        const text = await response.text();
        // 解析 HTML 或目录内容，获取文件数量
        const parser = new DOMParser();
        const doc = parser.parseFromString(text, "text/html");
        const files = Array.from(doc.querySelectorAll("a")).filter((link) =>
          /\.(mov|mp4|avi)$/i.test(link.href)
        );
        alert(`当前目录下的视频文件数量为：${files.length}`);
      } catch (error) {
        console.error(error);
        alert("获取视频文件数量失败");
      }
    };

    return {
      videoUrl,
      searched,
      handleSearch,
      getVideoCount,
    };
  },
};
</script>

